    [InlineData("GetFactors.java", "import java.util.*;\n\npublic class GetFactors {\n    public static ArrayList<Integer> get_factors(int n) {\n        if (n == 1) {\n            return new ArrayList<Integer>();\n        }\n        int max = (int)(Math.sqrt(n) + 1.0);\n        for (int i=2; i < max; i++) {\n            if (n % i == 0) {\n                ArrayList<Integer> prepend = new ArrayList<Integer>(0);\n                prepend.add(i);\n                prepend.addAll(get_factors(n / i));\n                return prepend;\n            }\n        }\n        return new ArrayList<Integer>(Arrays.asList(n));\n    }\n\n    public static void main(String[] args) {\n        StringJoiner lines = new StringJoiner(\"|\");\n        for (int n : new int[] {12, 60, 13, 100, 97}) {\n            StringJoiner factors = new StringJoiner(\" \");\n            for (int factor : get_factors(n)) factors.add(String.valueOf(factor));\n            lines.add(factors.toString());\n        }\n        System.out.println(lines);\n    }\n}\n")]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\npublic static class Program\n{\n    static List<int> Factors(int n)\n    {\n        if (n == 1)\n        {\n            return new List<int>();\n        }\n\n        for (var i = 2; i * i <= n; i++)\n        {\n            if (n % i == 0)\n            {\n                return new List<int> { i }.Concat(Factors(n / i)).ToList();\n            }\n        }\n\n        return new List<int> { n };\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine(string.Join(\"|\", new[] { 12, 60, 13, 100, 97 }.Select(n => string.Join(\" \", Factors(n)))));\n    }\n}\n")]
    [InlineData("is_prime.js", "// Whether a number is prime, its divisors looked for up to its square root: prints false true.\nfunction isPrime(n) {\n  for (let i = 2; i * i <= n; i++) {\n    if (n % i === 0) return false;\n  }\n  return true;\n}\n\nconsole.log(isPrime(12), isPrime(13));\n")]
    [InlineData("leftover.py", "# Each factor divided out in turn, and what is left after the search kept when it is above 1: prints 2 2 3|13.\ndef get_factors(n):\n    found = []\n    i = 2\n    while i * i <= n:\n        while n % i == 0:\n            found.append(i)\n            n //= i\n        i += 1\n    if n > 1:\n        found.append(n)\n    return found\n\n\nprint(\"|\".join(\" \".join(str(factor) for factor in get_factors(n)) for n in [12, 13]))\n")]
    [InlineData("smallest_divisor.py", "# The smallest divisor up to the square root, or none for a prime - not a list of factors: prints [2] [].\nimport math\n\n\ndef smallest_divisor(n):\n    for i in range(2, math.isqrt(n) + 1):\n        if n % i == 0:\n            return [i]\n    return []\n\n\nprint(smallest_divisor(12), smallest_divisor(13))\n")]
    [InlineData("to_the_number.py", "# The search going up to the number itself, so the last prime is found by the loop - QuixBugs' other right way: prints 2 2 3|13.\ndef get_factors(n):\n    if n == 1:\n        return []\n\n    for i in range(2, n + 1):\n        if n % i == 0:\n            return [i] + get_factors(n // i)\n\n    return []\n\n\nprint(\"|\".join(\" \".join(str(factor) for factor in get_factors(n)) for n in [12, 13]))\n")]
    public void TheLastFactorKeptIsLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("last-factor-dropped", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
